        ("p", "&sect;3", "an3.37:3.1-3.5"),
        ("h3", "Sakka&rsquo;s verse"),
        ("p", "&sect;4&ndash;5", "an3.37:4.1-5.6"),
        ("p", "&sect;6", "an3.37:6.1-6.3"),
